import java.util.*;
import java.lang.Math;

public class Main {
    static int mod;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        mod = sc.nextInt();

        List<Integer> dp = new ArrayList<>();
        dp.add(0);
        dp.add(1);
        int total = 1;

        for (int i = 2; i <= n; i++) {
            int max_f = (int) Math.sqrt(i) + 1;
            int sum_curr = total;

            for (int f = 2; f < max_f; f++) {
                sum_curr = mod_add(sum_curr, dp.get(i / f));
            }

            int end = i;
            for (int j = 1; j <= i / max_f; j++) {
                int val = i / (j + 1);
                sum_curr = mod_add(sum_curr, mod_mul(end - val, dp.get(j)));
                end = val;
            }

            total = mod_add(total, sum_curr);
            dp.add(sum_curr);
        }

        System.out.println(dp.get(dp.size() - 1));
    }

    static int get_input_as_list(Scanner sc, String dtype) {
        // Not used in Java implementation, as input is read directly
        return 0;
    }

    static int div_ceil(int a, int b) {
        return (a + b - 1) / b;
    }

    static int mod_add(int a, int b) {
        return (a + b) % mod;
    }

    static int mod_mul(int a, int b) {
        return (int)((long)a * b % mod);
    }
}
